    double sigma_norm_sq;
    double inv_norm_sq;

    if ((sigma == NULL) || (shadow == NULL) || (switched == NULL)) {
        return ADCS_E_NULL;
    }
    if (!adcs_is_finite_vec3(sigma)) {
        return ADCS_E_NOT_FINITE;
    }

    sigma_norm_sq = adcs_vec3_dot(sigma, sigma);

    if (sigma_norm_sq > 1.0) {
        inv_norm_sq = 1.0 / sigma_norm_sq;
        shadow->x = -sigma->x * inv_norm_sq;
        shadow->y = -sigma->y * inv_norm_sq;
        shadow->z = -sigma->z * inv_norm_sq;
        *switched = 1;
    } else {
        shadow->x = sigma->x;
        shadow->y = sigma->y;
        shadow->z = sigma->z;
        *switched = 0;
    }

    return ADCS_OK;
}

